package com.storyforge.platform.service;

import org.springframework.stereotype.Service;

import java.io.InputStream;
import java.net.HttpURLConnection;
import java.net.URI;
import java.net.URL;
import java.nio.charset.StandardCharsets;

@Service
public class ScriptFetchService {

    private static final int CONNECT_TIMEOUT_MS = 5000;
    private static final int READ_TIMEOUT_MS = 5000;

    public String fetchContent(String url) {
        HttpURLConnection connection = null;
        try {
            URL target = URI.create(url).toURL();
            connection = (HttpURLConnection) target.openConnection();
            connection.setRequestMethod("GET");
            connection.setConnectTimeout(CONNECT_TIMEOUT_MS);
            connection.setReadTimeout(READ_TIMEOUT_MS);
            int status = connection.getResponseCode();
            if (status != 200) {
                throw new RuntimeException("获取剧本内容失败，HTTP状态码: " + status);
            }
            try (InputStream in = connection.getInputStream()) {
                return new String(in.readAllBytes(), StandardCharsets.UTF_8);
            }
        } catch (RuntimeException e) {
            throw e;
        } catch (Exception e) {
            throw new RuntimeException("获取剧本内容失败: " + e.getMessage(), e);
        } finally {
            if (connection != null) {
                connection.disconnect();
            }
        }
    }
}

package com.storyforge.platform.service;

import com.storyforge.platform.dto.StoryboardCreateRequest;
import com.storyforge.platform.dto.StoryboardUpdateRequest;
import com.storyforge.platform.entity.Project;
import com.storyforge.platform.entity.Shot;
import com.storyforge.platform.entity.Storyboard;
import com.storyforge.platform.mapper.ProjectMapper;
import com.storyforge.platform.mapper.ShotMapper;
import com.storyforge.platform.mapper.StoryboardMapper;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;

@Service
public class StoryboardService {

    private final StoryboardMapper storyboardMapper;
    private final ShotMapper shotMapper;
    private final ProjectMapper projectMapper;
    private final ScriptFetchService scriptFetchService;
    private final Random random = new Random();

    public StoryboardService(StoryboardMapper storyboardMapper,
                             ShotMapper shotMapper,
                             ProjectMapper projectMapper,
                             ScriptFetchService scriptFetchService) {
        this.storyboardMapper = storyboardMapper;
        this.shotMapper = shotMapper;
        this.projectMapper = projectMapper;
        this.scriptFetchService = scriptFetchService;
    }

    public Storyboard create(StoryboardCreateRequest request, Long userId, String role) {
        Project project = request.getProjectId() == null
                ? null
                : projectMapper.findById(request.getProjectId());
        if (project == null || (!isAdmin(role) && !project.getOwnerId().equals(userId))) {
            throw new IllegalArgumentException("项目不存在");
        }

        Storyboard storyboard = new Storyboard();
        storyboard.setProjectId(request.getProjectId());
        storyboard.setTitle(request.getTitle());
        storyboard.setSourceUrl(request.getSourceUrl());
        storyboard.setStatus("DRAFT");
        storyboard.setShotCount(0);
        storyboard.setErrorMessage(null);
        storyboard.setOwnerId(userId);
        storyboard.setCreatedAt(LocalDateTime.now());
        storyboard.setUpdatedAt(null);

        String sourceUrl = request.getSourceUrl();
        if (sourceUrl != null && !sourceUrl.isBlank()) {
            try {
                storyboard.setScriptContent(scriptFetchService.fetchContent(sourceUrl));
            } catch (Exception e) {
                String fallback = request.getScriptContent();
                storyboard.setScriptContent(fallback != null && !fallback.isBlank() ? fallback : "");
            }
        } else {
            storyboard.setScriptContent(request.getScriptContent());
        }

        storyboardMapper.insert(storyboard);
        return storyboard;
    }

    public Storyboard update(Long id, StoryboardUpdateRequest request, Long userId, String role) {
        Storyboard storyboard = findAccessible(id, userId, role);
        if (storyboard == null) {
            return null;
        }

        if (request.getTitle() != null && !request.getTitle().isBlank()) {
            storyboard.setTitle(request.getTitle());
        }

        String sourceUrl = request.getSourceUrl();
        if (sourceUrl != null && !sourceUrl.isBlank()) {
            storyboard.setSourceUrl(sourceUrl);
            try {
                storyboard.setScriptContent(scriptFetchService.fetchContent(sourceUrl));
            } catch (Exception e) {
                if (request.getScriptContent() != null) {
                    storyboard.setScriptContent(request.getScriptContent());
                }
            }
        } else if (request.getScriptContent() != null) {
            storyboard.setScriptContent(request.getScriptContent());
        }

        storyboard.setUpdatedAt(LocalDateTime.now());
        storyboardMapper.update(storyboard);
        return storyboard;
    }

    public List<Storyboard> list(Long projectId, Long userId, String role) {
        if (projectId != null) {
            List<Storyboard> storyboards = storyboardMapper.findByProjectId(projectId);
            if (isAdmin(role)) {
                return storyboards;
            }
            return storyboards.stream()
                    .filter(storyboard -> userId.equals(storyboard.getOwnerId()))
                    .toList();
        }
        return isAdmin(role) ? storyboardMapper.findAll() : storyboardMapper.findByOwnerId(userId);
    }

    public Map<String, Object> detail(Long id, Long userId, String role) {
        Storyboard storyboard = findAccessible(id, userId, role);
        if (storyboard == null) {
            return null;
        }
        List<Shot> shots = shotMapper.findByStoryboardId(id);
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("id", storyboard.getId());
        data.put("projectId", storyboard.getProjectId());
        data.put("title", storyboard.getTitle());
        data.put("scriptContent", storyboard.getScriptContent());
        data.put("sourceUrl", storyboard.getSourceUrl());
        data.put("status", storyboard.getStatus());
        data.put("shotCount", storyboard.getShotCount());
        data.put("ownerId", storyboard.getOwnerId());
        data.put("createdAt", storyboard.getCreatedAt());
        data.put("updatedAt", storyboard.getUpdatedAt());
        data.put("shots", shots);
        return data;
    }

    @Transactional
    public Map<String, Object> generate(Long id, Long userId, String role) {
        Storyboard storyboard = findAccessible(id, userId, role);
        if (storyboard == null) {
            return null;
        }
        String script = storyboard.getScriptContent();
        if (script == null || script.isBlank()) {
            throw new IllegalArgumentException("故事板无剧本内容，无法生成分镜");
        }

        shotMapper.deleteByStoryboardId(id);

        String[] segments = script.split("[。\n]+");
        int sequence = 0;
        LocalDateTime now = LocalDateTime.now();
        for (String segment : segments) {
            String sceneDesc = segment.trim();
            if (sceneDesc.isEmpty()) {
                continue;
            }
            sequence++;
            Shot shot = new Shot();
            shot.setStoryboardId(id);
            shot.setSequence(sequence);
            shot.setSceneDesc(sceneDesc);
            shot.setDialogue(null);
            shot.setDuration(3 + random.nextInt(6));
            shot.setCreatedAt(now);
            shotMapper.insert(shot);
        }

        storyboard.setStatus("READY");
        storyboard.setShotCount(sequence);
        storyboard.setUpdatedAt(LocalDateTime.now());
        storyboardMapper.update(storyboard);

        Map<String, Object> result = new LinkedHashMap<>();
        result.put("id", storyboard.getId());
        result.put("status", storyboard.getStatus());
        result.put("shotCount", storyboard.getShotCount());
        return result;
    }

    private Storyboard findAccessible(Long id, Long userId, String role) {
        Storyboard storyboard = storyboardMapper.findById(id);
        if (storyboard == null || (!isAdmin(role) && !storyboard.getOwnerId().equals(userId))) {
            return null;
        }
        return storyboard;
    }

    private boolean isAdmin(String role) {
        return "ADMIN".equals(role);
    }
}

package com.storyforge.platform.util;

import com.storyforge.platform.entity.User;
import com.storyforge.platform.mapper.UserMapper;
import org.springframework.boot.CommandLineRunner;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.stereotype.Component;

import java.time.LocalDateTime;

@Component
public class DataInitializer implements CommandLineRunner {

    private final UserMapper userMapper;
    private final BCryptPasswordEncoder passwordEncoder = new BCryptPasswordEncoder();

    public DataInitializer(UserMapper userMapper) {
        this.userMapper = userMapper;
    }

    @Override
    public void run(String... args) {
        if (userMapper.count() > 0) {
            return;
        }
        LocalDateTime now = LocalDateTime.now();
        seedUser("admin", "admin123", "ADMIN", now);
        seedUser("user1", "user123", "USER", now);
        seedUser("user2", "user456", "USER", now);
    }

    private void seedUser(String username, String rawPassword, String role, LocalDateTime createdAt) {
        User user = new User();
        user.setUsername(username);
        user.setPassword(passwordEncoder.encode(rawPassword));
        user.setRole(role);
        user.setCreatedAt(createdAt);
        userMapper.insert(user);
    }
}
